mapper.select:
/*CmnCdDAO.selectListCmnCd 공통코드 목록 조회 */ SELECT CD_GROUP_VAL /* 코드그룹값 */ , CD_VAL /* 코드값 */ , CD_NM /* 코드명 */ , DESC_CTNT /* 설명내용 */ , REPST_ORDR /* 표시순서 */ , CD_REF_1_VAL /* 코드참조1값 */ , CD_REF_2_VAL /* 코드참조2값 */ , CD_REF_3_VAL /* 코드참조3값 */ , UP_CD_GROUP_VAL /* 상위코드그룹값 */ , UP_CD_VAL /* 상위코드값 */ , USE_YN /* 사용여부 */ , FRST_REGI_USER_ID /* 최초등록사용자아이디 */ , FRST_REGI_TMSP /* 최초등록타임스탬프 */ , LAST_CHNG_USER_ID /* 최종변경사용자아이디 */ , LAST_CHNG_TMSP /* 최종변경타임스탬프 */ FROM CMN_CD WHERE 1=1
AND CD_GROUP_VAL=#{cdGroupVal}
AND CD_VAL LIKE CONCAT('%', #{cdVal},'%')
ORDER BY REPST_ORDR

SELECT COUNT(*) AS totalCount FROM CMN_CD WHERE CD_GROUP_VAL=#{cdGroupVal}
AND CD_VAL LIKE CONCAT('%', #{cdVal},'%')
AND USE_YN = #{useYn}
ORDER BY REPST_ORDR

mapper.update:
/*CmnCdDAO.updateMergeCmnCd 공통코드 등록 Merge*/
INSERT INTO CMN_CD (
		 CD_GROUP_VAL
	   , CD_VAL
	   , CD_NM
	   , DESC_CTNT
	   , REPST_ORDR
	   , CD_REF_1_VAL
	   , CD_REF_2_VAL
	   , CD_REF_3_VAL
	   , UP_CD_GROUP_VAL
	   , UP_CD_VAL
	   , USE_YN
	   , FRST_REGI_USER_ID
	   , FRST_REGI_TMSP
)
VALUES (
		 #{cdGroupVal}
	   , #{cdVal}
	   , #{cdNm}
	   , #{descCtnt}
	   , #{repstOrdr}
	   , #{cdRef1Val}
	   , #{cdRef2Val}
	   , #{cdRef3Val}
	   , #{upCdGroupVal}
	   , #{upCdVal}
	   , #{useYn}
	   , #{frstRegiUserId}
	   , CURRENT_TIMESTAMP()
	   )
	ON DUPLICATE KEY UPDATE
						   CD_NM = #{cdNm}
						 , DESC_CTNT = #{descCtnt}
						 , REPST_ORDR = #{repstOrdr}
						 , CD_REF_1_VAL = #{cdRef1Val}
						 , CD_REF_2_VAL = #{cdRef2Val}
						 , CD_REF_3_VAL = #{cdRef3Val}
						 , UP_CD_GROUP_VAL = #{upCdGroupVal}
						 , UP_CD_VAL = #{upCdVal}
						 , USE_YN = #{useYn}
						 , LAST_CHNG_USER_ID = #{lastChngUserId}
						 , LAST_CHNG_TMSP = CURRENT_TIMESTAMP()
